periods.description:
@@preprocessing
<%_ {
const data=getMessageVar('stat_data',{defaults:{}}),world=_.get(data,'世界',{}),player=_.get(data,'玩家',{}),characters=_.get(data,'角色',{});
const ids=[...new Set([...(world.當前場景角色ID||[]),...Object.keys(_.get(player,'隊伍.成員',{})||{})])].filter(id=>id!=='player'&&characters[id]);
const relevant=Object.fromEntries(ids.map(id=>[id,{名稱:characters[id].名稱,性別:characters[id].性別,身份:characters[id].身份,近況:characters[id].近況,對玩家關係:characters[id].對玩家關係}]));
const femaleNames=ids.filter(id=>String(characters[id]?.性別||'').includes('女')).map(id=>characters[id].名稱);
const library=femaleNames.length?await getwi('关系阶段·女性角色资料库'):'';
_%>
<SAO_RELATION_ROUTER version="5.1.1">
當前相關角色：<%- JSON.stringify(relevant) %>
<%= library %>
規則：
1. 關係唯一保存於`/角色/<角色ID>/對玩家關係`，介面只讀顯示好感、階段與摘要。
2. AI可直接更新關係摘要、標籤、邊界與已確認關鍵記憶；好感數值與階段只能提交`關係`UnifiedAction，由腳本限制範圍並計算階段。
3. 角色ID是路徑鍵，名稱只作顯示。不得以譯名、暱稱或繁簡差異另建同一人物。
4. 離場且未涉及本輪任務或事件的角色不更新。
5. 人物頁面沒有直接修改、刪除、裝備、物品或技能按鈕；互動按鈕只建立行動或訊息。
</SAO_RELATION_ROUTER>
<%_ } _%>
